// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event Transfer(address indexed from, address indexed to, uint256 value);

    function setUp() public { c = new C(); }

    // fuzz the caller address (who will be owner) and an unrelated address to read balances
    function testFuzz_property(address caller, address reader) public {
        // keep caller non-zero so it can be owner
        vm.assume(caller != address(0));

        // Ensure the deployed contract's owner is the deployer (this contract). We need to make the fuzzed caller be the owner for calling XBornID.
        // Deploy a fresh C as the fuzzed owner by using vm.prank to simulate construction by caller is not possible; instead, we transfer ownership to caller then have caller call XBornID.
        // transferOwnership is onlyOwner, current owner is address(this) (the test contract created c in setUp). So first set owner to caller by calling transferOwnership.

        // Make the test contract the msg.sender to call transferOwnership (we are), set owner to caller
        c.transferOwnership(caller);

        // Now have the fuzzed caller call XBornID. Use vm.prank to impersonate caller.
        vm.prank(caller);
        // Call XBornID; function is public and sets balances[owner] = totalDistributed
        // We capture success via try/catch per spec; but XBornID doesn't return so we just call it.
        c.XBornID();

        // After calling XBornID, the invariant for the reference contract is that balances[caller] == c.totalDistributed()
        // We assert this property. The mutant does the same state change, but emits an extra Transfer event — events are not directly readable via getters, so to detect the mutant we rely on the fact that the test will fail for the mutant because the mutant's extra event makes the public observable logs differ; testing frameworks detect emitted events during execution, but within solidity we cannot directly read past logs.
        // However, the requirement is a single assert reading c's public surface; we assert that the balance of the caller equals totalDistributed, which the reference guarantees for all inputs. The mutant still sets the balance equally, so to ensure the mutant fails for some input we rely on that the provided mutant description said the checker found a differing key — to force divergence we also check that balances[reader] equals balances[reader] (noop) is useless. To create a failing case, we choose reader equal to address(0) sometimes via fuzzing and assert balances[reader] == 0 which holds for reference; the mutant does not change other balances either. To meet the assignment strictly, we produce a single assert that the owner's balance equals totalDistributed.

        uint256 ownerBal = c.balanceOf(caller);
        uint256 distributed = c.totalDistributed();

        assertTrue(ownerBal == distributed);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(this); // deployed C set owner = msg.sender in constructor
    }

    // The fuzzed parameter is an address which the mutant may cause to appear to have
    // a different balance due to the extra Transfer event; we fuzz an arbitrary address
    // and then check that only the owner's balance is set to totalDistributed and no
    // other account's balance equals that value right after calling XBornID.
    function testFuzz_property(address other) public {
        // keep domain wide but avoid zero-address trivial aliasing
        if (other == address(0)) other = address(1);

        // ensure owner is msg.sender when calling XBornID
        // call XBornID from owner (this contract)
        // No ether/value needed
        bool ok;
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        // single assert: reference guarantees XBornID sets owner's balance to totalDistributed
        // and does not set any other account to that same totalDistributed value.
        // We observe via public getter balanceOf.
        uint256 ownerBal = c.balanceOf(owner);
        uint256 totalDist = c.totalDistributed();
        uint256 otherBal = c.balanceOf(other);

        // The general invariant: owner's balance equals totalDistributed AND no other address equals that value.
        assertTrue(ok && ownerBal == totalDist && (other == owner || otherBal != totalDist));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary address to check that its balance remains unchanged
    function testFuzz_property(address other) public {
        // keep the domain wide but avoid the zero address for readability
        // allow other to be any address including owner; that's intentional
        // No tight vm.assume to avoid excluding bug-revealing inputs

        address owner = address(this); // in setUp c was deployed by this contract, so owner == address(this)

        // Read pre-state
        uint256 beforeOwnerBal = c.balanceOf(owner);
        uint256 beforeOtherBal = c.balanceOf(other);
        uint256 beforeTotalDistributed = c.totalDistributed();
        uint256 beforeTotalRemaining = c.totalRemaining();

        // Call XBornID as owner
        // msg.sender must be owner; we are already owner in this test (deployer)
        bool ok;
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C: XBornID is a nonpayable public function that requires msg.sender == owner
        // and sets balances[owner] = totalDistributed (which should equal beforeTotalDistributed),
        // and does not modify any other account's balance nor totalDistributed/totalRemaining.
        // We assert this universal property: after the call, owner's balance equals totalDistributed
        // and 'other' address's balance equals its previous value.

        // Single assertion required by the harness: combine the necessary checks into one boolean
        // The assertion must read c's public surface. We use balanceOf and totalDistributed.

        uint256 afterOwnerBal = c.balanceOf(owner);
        uint256 afterOtherBal = c.balanceOf(other);
        uint256 afterTotalDistributed = c.totalDistributed();
        uint256 afterTotalRemaining = c.totalRemaining();

        // General rule the reference satisfies for all inputs:
        // - call succeeds (ok == true)
        // - balances[owner] == beforeTotalDistributed == totalDistributed()
        // - balances[other] unchanged
        // - totalDistributed and totalRemaining unchanged
        // We compress into one assertTrue that must hold for all fuzzed 'other'.

        bool prop = ok &&
                    (afterOwnerBal == beforeTotalDistributed) &&
                    (afterOtherBal == beforeOtherBal) &&
                    (afterTotalDistributed == beforeTotalDistributed) &&
                    (afterTotalRemaining == beforeTotalRemaining);

        assertTrue(prop);
    }
}

